    //
    aIngress = 0xE91FBCBE919D19C7ULL;
    aCarry = 0x92C955405BB80013ULL;
    aWandererA = 0xB0F8079B72D35A38ULL;
    aWandererB = 0xCEEC9760569B6B26ULL;
