    std::uint64_t aWandererI = 0U; std::uint64_t aWandererJ = 0U; std::uint64_t aWandererK = 0U;

    // [twist]
    aIngress = 0xCCF321C5C9033693ULL;
    aCarry = 0x99B700A2CB2BB546ULL;
    aWandererA = 0xE3CBA5464D440548ULL;
    aWandererB = 0xE4FC34A4B809CCE5ULL;
